export const envelope = [27, 18, 27];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const cx = 13;
  const cz = 13;
  const seatY = 3;
  const daisY = 5;

  // Safe voxel writer respecting envelope boundaries
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  // Terrain height helper mapped to node-local coordinates
  function getGroundY(x, z) {
    return Math.floor(seatY + api.heightAt(x, z));
  }

  // Theme roles & blocks
  const woodLogY = api.theme.wood.log + "[axis=y]";
  const woodLogX = api.theme.wood.log + "[axis=x]";
  const woodLogZ = api.theme.wood.log + "[axis=z]";
  const woodPlanks = api.theme.wood.planks;
  const woodFence = api.theme.wood.fence;
  const woodStairsS = api.theme.wood.stairs + "[facing=south,half=bottom,shape=straight]";
  const woodStairsN = api.theme.wood.stairs + "[facing=north,half=bottom,shape=straight]";
  const woodStairsE = api.theme.wood.stairs + "[facing=east,half=bottom,shape=straight]";
  const woodStairsW = api.theme.wood.stairs + "[facing=west,half=bottom,shape=straight]";
  const roofStairsN = api.theme.roof.stairs + "[facing=north,half=bottom,shape=straight]";
  const roofSlab = api.theme.roof.slab + "[type=bottom]";
  const plinthBlock = api.theme.ground.plinth;

  // Traditional felt materials & steppe embellishments
  const whiteFelt = "minecraft:white_wool";
  const redFelt = "minecraft:red_wool";
  const blueFelt = "minecraft:blue_wool";
  const yellowFelt = "minecraft:yellow_wool";
  const goldBlock = "minecraft:gold_block";
  const hangingLantern = "minecraft:lantern[hanging=true]";
  const standingLantern = "minecraft:lantern[hanging=false]";

  // --- 1. Ornamental Timber Dais Platform & Conforming Footing ---
  const daisRadius = 12.2;
  const daisRadiusSq = daisRadius * daisRadius;

  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const d2 = dx * dx + dz * dz;
      const isDais = d2 <= daisRadiusSq;
      const isSteps = x >= 11 && x <= 15 && z >= 0 && z <= 3;

      if (!isDais && !isSteps) continue;

      const groundY = getGroundY(x, z);
      const botY = Math.max(0, Math.min(seatY, groundY));

      let topY = daisY;
      let isStairStep = false;

      if (isSteps) {
        if (z === 0) topY = Math.max(botY, seatY - 1);
        else if (z === 1) { topY = seatY; isStairStep = true; }
        else if (z === 2) { topY = seatY + 1; isStairStep = true; }
        else if (z === 3) { topY = daisY; }
      }

      // Foundation downward to terrain
      for (let y = botY; y < topY; y++) {
        if (y < seatY) {
          setBlock(x, y, z, plinthBlock);
        } else if (d2 > 10.5 * 10.5 && !isSteps) {
          setBlock(x, y, z, woodLogY);
        } else {
          setBlock(x, y, z, woodPlanks);
        }
      }

      // Surface course
      if (isStairStep) {
        setBlock(x, topY, z, woodStairsS);
      } else {
        if (d2 > 11.2 * 11.2 && !isSteps) {
          setBlock(x, topY, z, woodLogY);
        } else {
          setBlock(x, topY, z, woodPlanks);
        }
      }
    }
  }

  // --- 2. Dais Railings & Perimeter Lantern Posts ---
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const d2 = dx * dx + dz * dz;

      // On the outer lip of the dais, excluding front entrance
      if (d2 <= daisRadiusSq && d2 >= 11.0 * 11.0) {
        if (x >= 10 && x <= 16 && z <= 4) continue; // Entrance gap

        setBlock(x, daisY + 1, z, woodFence);

        // Accent posts with lanterns
        if ((x === 3 || x === 23) && (z === 13 || z === 19 || z === 7)) {
          setBlock(x, daisY + 2, z, woodFence);
          setBlock(x, daisY + 3, z, standingLantern);
        }
      }
    }
  }

  // --- 3. Khan's Horsetail War Standards (Nine White Sulde) ---
  const standardPositions = [
    [10, 2], [16, 2],  // Entrance guard standards
    [3, 9],  [23, 9],  // Flank standards
    [4, 18], [22, 18], // Rear quarter standards
    [13, 24]           // High rear standard
  ];

  for (const [sx, sz] of standardPositions) {
    const groundY = getGroundY(sx, sz);
    const botY = Math.max(0, Math.min(seatY, groundY));

    for (let y = botY; y <= daisY; y++) {
      setBlock(sx, y, sz, woodLogY);
    }
    setBlock(sx, daisY + 1, sz, woodPlanks);

    // Standard pole
    for (let y = daisY + 2; y <= daisY + 6; y++) {
      setBlock(sx, y, sz, woodFence);
    }

    // Cross-arm and horsetail tassels
    const crossY = daisY + 5;
    setBlock(sx - 1, crossY, sz, woodFence);
    setBlock(sx + 1, crossY, sz, woodFence);
    setBlock(sx - 1, crossY - 1, sz, whiteFelt);
    setBlock(sx + 1, crossY - 1, sz, whiteFelt);
    setBlock(sx, crossY - 1, sz, whiteFelt);

    // Spearhead trident finial
    setBlock(sx, daisY + 7, sz, goldBlock);
    setBlock(sx, daisY + 8, sz, woodFence);
  }

  // --- 4. Grand North Entrance Canopy ---
  // Entrance timber pillars
  for (let y = daisY; y <= daisY + 3; y++) {
    setBlock(11, y, 3, woodLogY);
    setBlock(15, y, 3, woodLogY);
  }
  // Lintel
  for (let x = 11; x <= 15; x++) {
    setBlock(x, daisY + 3, 3, woodLogX);
  }
  // Canopy eaves & overhang
  for (let x = 10; x <= 16; x++) {
    setBlock(x, daisY + 4, 2, roofStairsN);
    setBlock(x, daisY + 4, 3, roofSlab);
  }
  // Entrance lanterns
  setBlock(11, daisY + 2, 2, hangingLantern);
  setBlock(15, daisY + 2, 2, hangingLantern);

  // --- 5. Internal Bagana (Four Great Central Pillars) ---
  const pillarCoords = [
    [10, 10], [16, 10],
    [10, 16], [16, 16]
  ];

  for (const [px, pz] of pillarCoords) {
    for (let y = daisY; y <= daisY + 8; y++) {
      setBlock(px, y, pz, woodLogY);
    }
    // Capital brackets under Toono
    setBlock(px, daisY + 9, pz, woodPlanks);
  }
  // Collar tie cross beams between pillars
  for (let x = 11; x <= 15; x++) {
    setBlock(x, daisY + 7, 10, woodFence);
    setBlock(x, daisY + 7, 16, woodFence);
  }
  for (let z = 11; z <= 15; z++) {
    setBlock(10, daisY + 7, z, woodFence);
    setBlock(16, daisY + 7, z, woodFence);
  }

  // --- 6. Cylindrical Felt Wall (Khana Drum) ---
  const wallRMin = 8.2;
  const wallRMax = 9.4;

  for (let x = 3; x <= 23; x++) {
    for (let z = 3; z <= 23; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist >= wallRMin && dist <= wallRMax) {
        // Doorway void at the front (North)
        const isDoorway = x >= 12 && x <= 14 && z <= 5 && z >= 3;

        for (let y = daisY; y <= daisY + 4; y++) {
          if (isDoorway) {
            if (y === daisY) {
              setBlock(x, y, z, woodPlanks);
            } else if (y === daisY + 4) {
              setBlock(x, y, z, woodLogX);
            }
            // Air opening at daisY + 1 .. daisY + 3
            continue;
          }

          const angle = Math.atan2(dz, dx);

          if (y === daisY) {
            // Lower crimson rim
            setBlock(x, y, z, redFelt);
          } else if (y === daisY + 1 || y === daisY + 3) {
            // Main white felt body
            setBlock(x, y, z, whiteFelt);
          } else if (y === daisY + 2) {
            // Traditional nomad geometric wave embroidery
            const sector = Math.floor(((angle + Math.PI) / (Math.PI / 6))) % 2;
            const motifBlock = sector === 0 ? blueFelt : yellowFelt;
            setBlock(x, y, z, motifBlock);
          } else if (y === daisY + 4) {
            // Upper eave felt border
            setBlock(x, y, z, redFelt);
          }
        }
      }
    }
  }

  // --- 7. Conical Domed Felt Roof & Radial Straps (Uni Rafters) ---
  const roofLayers = [
    { y: daisY + 5, rMin: 6.8, rMax: 8.2 },
    { y: daisY + 6, rMin: 5.4, rMax: 6.8 },
    { y: daisY + 7, rMin: 4.0, rMax: 5.4 },
    { y: daisY + 8, rMin: 2.6, rMax: 4.0 }
  ];

  for (const layer of roofLayers) {
    for (let x = 4; x <= 22; x++) {
      for (let z = 4; z <= 22; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);

        if (dist >= layer.rMin && dist <= layer.rMax) {
          const angle = (Math.atan2(dz, dx) + 2 * Math.PI) % (2 * Math.PI);

          // 8 radial felt tension straps
          const strapIndex = Math.round(8 * (angle / (2 * Math.PI))) % 8;
          const strapAngle = strapIndex * (Math.PI / 4);
          let angleDiff = Math.abs(angle - strapAngle);
          if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;

          const isStrap = angleDiff < 0.16;

          if (isStrap) {
            setBlock(x, layer.y, z, redFelt);
          } else if (layer.y === daisY + 6 && dist >= 5.8 && dist <= 6.3) {
            // Middle decorative blue felt ring
            setBlock(x, layer.y, z, blueFelt);
          } else {
            setBlock(x, layer.y, z, whiteFelt);
          }
        }
      }
    }
  }

  // --- 8. The Grand Toono (Royal Smoke-Ring Crown & Finial) ---
  const toonoY = daisY + 9;

  for (let x = 9; x <= 17; x++) {
    for (let z = 9; z <= 17; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);

      // Wooden crown ring
      if (dist >= 2.0 && dist <= 3.5) {
        setBlock(x, toonoY, z, woodLogY);
      }

      // Wheel spokes across the crown
      if (dist < 2.0) {
        if (dx === 0 || dz === 0 || Math.abs(dx) === Math.abs(dz)) {
          setBlock(x, toonoY, z, woodFence);
        }
      }

      // Raised cupola rim
      if (dist >= 2.0 && dist <= 3.0) {
        setBlock(x, toonoY + 1, z, woodFence);
      }
    }
  }

  // Central apex standard & golden imperial sun disc
  setBlock(cx, toonoY, cz, woodLogY);
  setBlock(cx, toonoY + 1, cz, woodLogY);
  setBlock(cx, toonoY + 2, cz, goldBlock);
  setBlock(cx, toonoY + 3, cz, woodFence);

  // Cross tassels on the royal finial
  setBlock(cx - 1, toonoY + 2, cz, woodFence);
  setBlock(cx + 1, toonoY + 2, cz, woodFence);
  setBlock(cx, toonoY + 2, cz - 1, woodFence);
  setBlock(cx, toonoY + 2, cz + 1, woodFence);

  setBlock(cx - 1, toonoY + 1, cz, whiteFelt);
  setBlock(cx + 1, toonoY + 1, cz, whiteFelt);
  setBlock(cx, toonoY + 1, cz - 1, whiteFelt);
  setBlock(cx, toonoY + 1, cz + 1, whiteFelt);

  return {
    name: "Khan's Great Tent",
    seatY,
    anchors: {
      front: [cx, daisY, 0],
      door: [cx, daisY + 1, 3]
    },
    interiors: [
      {
        min: [7, daisY + 1, 7],
        max: [19, daisY + 6, 19],
        kind: "hall"
      }
    ]
  };
}
